import React from 'react';
import { BrowserRouter as Router, Route, Switch, NavLink } from 'react-router-dom';
import Dashboard from './Dashboard';
import MalwareLab from './MalwareLab';
import VulnScanner from './VulnScanner';
import Auth from './Auth';

function App() {
  return (
    <Router>
      <nav className="navbar navbar-expand-lg navbar-dark bg-dark">
        <a className="navbar-brand" href="/">CyberShield Lab</a>
        <div className="collapse navbar-collapse">
          <ul className="navbar-nav mr-auto">
            <li className="nav-item"><NavLink className="nav-link" to="/">Dashboard</NavLink></li>
            <li className="nav-item"><NavLink className="nav-link" to="/malware">Malware Lab</NavLink></li>
            <li className="nav-item"><NavLink className="nav-link" to="/vuln">Vuln Scanner</NavLink></li>
            <li className="nav-item"><NavLink className="nav-link" to="/auth">Auth Demo</NavLink></li>
          </ul>
        </div>
      </nav>
      <div className="container mt-4">
        <Switch>
          <Route exact path="/" component={Dashboard} />
          <Route path="/malware" component={MalwareLab} />
          <Route path="/vuln" component={VulnScanner} />
          <Route path="/auth" component={Auth} />
        </Switch>
      </div>
    </Router>
  );
}

export default App;
